motor_dir:
if (u_ctrl > $signed(DEADBAND[15:0])) begin
    // 正转：IN1=1, IN2=0
    in1     <= 1'b1;
    in2     <= 1'b0;
    pwm_run <= 1'b1;
    cmp     <= u_abs_lim[12:0];
end else if (u_ctrl < -$signed(DEADBAND[15:0])) begin
    // 反转：IN1=0, IN2=1
    in1     <= 1'b0;
    in2     <= 1'b1;
    pwm_run <= 1'b1;
    cmp     <= u_abs_lim[12:0];
end else begin
    // 死区：停机（IN1=IN2=0），PWM 强制为 0
    in1     <= 1'b0;
    in2     <= 1'b0;
    pwm_run <= 1'b0;
    cmp     <= 13'd0;

